def predict(x, class_centers):
    distances = [(x[0] - c[0]) ** 2 + (x[1] - c[1]) ** 2 for c in class_centers]
    return distances.index(min(distances))

print(predict([4.8, 5.9], [[1.0, 2.0], [5.0, 6.0]]))

def nearest(point, centers):
    distances = [(point[0] - c[0]) ** 2 + (point[1] - c[1]) ** 2 for c in centers]
    return distances.index(min(distances))

print(nearest([1.1, 2.0], [[1.0, 2.0], [5.0, 6.0]]))
